var builder = WebApplication.CreateBuilder(args);

// 1. Configure Redis Distributed Caching
builder.Services.AddStackExchangeRedisCache(options =>
{
    options.Configuration = builder.Configuration.GetConnectionString("RedisCache");
    options.InstanceName = "NexusProd_";
});

// 2. Share Data Protection Keys across all horizontal nodes
builder.Services.AddDataProtection()
    .PersistKeysToAzureBlobStorage(
        new Uri(builder.Configuration["Storage:DataProtectionBlobUri"]!),
        new DefaultAzureCredential())
    .ProtectKeysWithAzureKeyVault(
        new Uri(builder.Configuration["KeyVault:KeyEncryptionKeyUri"]!),
        new DefaultAzureCredential());

// 3. Register Stateless Session State backed by Redis
builder.Services.AddSession(options =>
{
    options.IdleTimeout = TimeSpan.FromMinutes(30);
    options.Cookie.HttpOnly = true;
    options.Cookie.IsEssential = true;
});

public interface IReadOnlyAppDbContext : IDisposable
{
    IQueryable<DocumentChunk> DocumentChunks { get; }
    IQueryable<ConversationSession> ConversationSessions { get; }
}

// In Program.cs: Register Write Context
builder.Services.AddDbContext<AppDbContext>(options =>
    options.UseNpgsql(builder.Configuration.GetConnectionString("PrimaryWriteConnection")));

// Register Read-Only Context pointing to Read Replica
builder.Services.AddDbContext<ReadOnlyAppDbContext>(options =>
    options.UseNpgsql(builder.Configuration.GetConnectionString("ReadReplicaConnection"))
           .UseQueryTrackingBehavior(QueryTrackingBehavior.NoTracking));
